{
 "title": "應稅所得計算卡",
 "topic": "稅務計算",
 "output": {
  "name": "taxable_income",
  "label": "應稅所得",
  "unit": "元"
 },
 "slots": [
  {
   "name": "gross_income",
   "label": "總收入",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "above_the_line_deductions",
   "label": "線之上扣除額",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "standard_deduction",
   "label": "標準扣除額",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "itemized_deductions",
   "label": "列舉扣除額",
   "kind": "money",
   "unit": "元"
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "deduction_choice",
   "text": "本計算使用標準扣除額與列舉扣除額中較大者。"
  },
  {
   "name": "non_negative_inputs",
   "text": "所有輸入值（收入與扣除額）均為非負數。"
  }
 ],
 "invariants": [
  {
   "id": "pre_gross_income_non_negative",
   "kind": "pre",
   "text": "總收入必須為非負數。",
   "check": "gross_income >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_atl_deductions_non_negative",
   "kind": "pre",
   "text": "線之上扣除額必須為非負數。",
   "check": "above_the_line_deductions >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_std_deduction_non_negative",
   "kind": "pre",
   "text": "標準扣除額必須為非負數。",
   "check": "standard_deduction >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_item_deductions_non_negative",
   "kind": "pre",
   "text": "列舉扣除額必須為非負數。",
   "check": "itemized_deductions >= 0",
   "source": "dbc"
  },
  {
   "id": "post_no_deductions",
   "kind": "post",
   "text": "當所有扣除額為零時，應稅所得應等於總收入。",
   "check": "close(f(gross_income, 0, 0, 0), gross_income)",
   "source": "dbc"
  },
  {
   "id": "post_zero_gross_income_zero_deductions",
   "kind": "post",
   "text": "當總收入和所有扣除額均為零時，應稅所得應為零。",
   "check": "close(f(0, 0, 0, 0), 0)",
   "source": "dbc"
  },
  {
   "id": "post_deductions_equal_agi",
   "kind": "post",
   "text": "當調整後總收入等於有效扣除額時，應稅所得應為零。",
   "check": "close(f(1000, 0, 1000, 0), 0)",
   "source": "dbc"
  },
  {
   "id": "meta_gross_income_additivity",
   "kind": "meta",
   "text": "總收入增加 X，應稅所得也增加 X。",
   "check": "close(f(gross_income + 1000, above_the_line_deductions, standard_deduction, itemized_deductions), result + 1000)",
   "source": "metamorphic"
  },
  {
   "id": "meta_atl_deductions_subtractivity",
   "kind": "meta",
   "text": "線之上扣除額增加 X，應稅所得減少 X。",
   "check": "close(f(gross_income, above_the_line_deductions + 1000, standard_deduction, itemized_deductions), result - 1000)",
   "source": "metamorphic"
  },
  {
   "id": "meta_deductions_monotonicity_std",
   "kind": "meta",
   "text": "增加標準扣除額不會增加應稅所得。",
   "check": "f(gross_income, above_the_line_deductions, standard_deduction + 100, itemized_deductions) <= result + 1e-9",
   "source": "metamorphic"
  },
  {
   "id": "meta_deductions_monotonicity_item",
   "kind": "meta",
   "text": "增加列舉扣除額不會增加應稅所得。",
   "check": "f(gross_income, above_the_line_deductions, standard_deduction, itemized_deductions + 100) <= result + 1e-9",
   "source": "metamorphic"
  },
  {
   "id": "meta_deduction_choice_symmetry",
   "kind": "meta",
   "text": "交換標準扣除額與列舉扣除額的值，結果應相同。",
   "check": "close(f(gross_income, above_the_line_deductions, standard_deduction, itemized_deductions), f(gross_income, above_the_line_deductions, itemized_deductions, standard_deduction))",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此卡片涵蓋了應稅所得計算的核心邏輯不變量，但未涵蓋所有可能的稅法細節或邊界情況，例如負數應稅所得的處理（虧損結轉）等。"
}

{
 "title": "收入需求彈性",
 "topic": "經濟學 / 彈性分析",
 "output": {
  "name": "elasticity",
  "label": "收入需求彈性",
  "unit": "無單位"
 },
 "slots": [
  {
   "name": "initial_income",
   "label": "初始收入",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "final_income",
   "label": "最終收入",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "initial_quantity",
   "label": "初始需求量",
   "kind": "number",
   "unit": "單位"
  },
  {
   "name": "final_quantity",
   "label": "最終需求量",
   "kind": "number",
   "unit": "單位"
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "percentage_change_base",
   "text": "百分比變化以初始值為基礎計算"
  },
  {
   "name": "ceteris_paribus",
   "text": "假設其他影響需求的因素保持不變"
  }
 ],
 "invariants": [
  {
   "id": "pre_initial_income_positive",
   "kind": "pre",
   "text": "初始收入必須為正數，否則無法計算百分比變化",
   "check": "initial_income > 0",
   "source": "dbc"
  },
  {
   "id": "pre_initial_quantity_positive",
   "kind": "pre",
   "text": "初始需求量必須為正數，否則無法計算百分比變化",
   "check": "initial_quantity > 0",
   "source": "dbc"
  },
  {
   "id": "pre_income_change",
   "kind": "pre",
   "text": "收入必須發生變化 (最終收入不等於初始收入)，否則收入百分比變化為零，導致彈性為無限大或未定義",
   "check": "final_income != initial_income",
   "source": "dbc"
  },
  {
   "id": "post_zero_quantity_change",
   "kind": "post",
   "text": "若需求量不變，則彈性為零 (假設收入有變化)",
   "check": "close(f(initial_income, final_income, initial_quantity, initial_quantity), 0)",
   "source": "base_case"
  },
  {
   "id": "post_unit_elasticity",
   "kind": "post",
   "text": "若收入和需求量都加倍，則彈性為 1",
   "check": "close(f(initial_income, 2 * initial_income, initial_quantity, 2 * initial_quantity), 1)",
   "source": "base_case"
  },
  {
   "id": "post_elastic_normal_good",
   "kind": "post",
   "text": "若收入增加10%導致需求量增加20%，則彈性為 2",
   "check": "close(f(initial_income, 1.1 * initial_income, initial_quantity, 1.2 * initial_quantity), 2)",
   "source": "base_case"
  },
  {
   "id": "post_inferior_good",
   "kind": "post",
   "text": "若收入增加10%導致需求量減少10%，則彈性為 -1",
   "check": "close(f(initial_income, 1.1 * initial_income, initial_quantity, 0.9 * initial_quantity), -1)",
   "source": "base_case"
  },
  {
   "id": "meta_scale_income",
   "kind": "meta",
   "text": "同時等比例縮放初始和最終收入 (例如都加倍)，不改變彈性",
   "check": "close(f(2 * initial_income, 2 * final_income, initial_quantity, final_quantity), result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_scale_quantity",
   "kind": "meta",
   "text": "同時等比例縮放初始和最終需求量 (例如都加倍)，不改變彈性",
   "check": "close(f(initial_income, final_income, 2 * initial_quantity, 2 * final_quantity), result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_sign_normal_good",
   "kind": "meta",
   "text": "若收入和需求量同向變化 (同增或同減)，則彈性為正 (正常財)",
   "check": "((final_income > initial_income and final_quantity > initial_quantity) or (final_income < initial_income and final_quantity < initial_quantity)) == (result > 0)",
   "source": "metamorphic"
  },
  {
   "id": "meta_sign_inferior_good",
   "kind": "meta",
   "text": "若收入和需求量反向變化 (一增一減)，則彈性為負 (劣等財)",
   "check": "((final_income > initial_income and final_quantity < initial_quantity) or (final_income < initial_income and final_quantity > initial_quantity)) == (result < 0)",
   "source": "metamorphic"
  }
 ]
}

{
 "title": "買入賣權損益計算",
 "topic": "選擇權策略",
 "output": {
  "name": "profit",
  "label": "總損益",
  "unit": "元"
 },
 "slots": [
  {
   "name": "stock_price_at_purchase",
   "label": "買入時股價",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "strike_price",
   "label": "履約價",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "premium_paid",
   "label": "每股權利金",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "shares_per_option",
   "label": "每份合約股數",
   "kind": "count",
   "unit": "股"
  },
  {
   "name": "final_stock_price",
   "label": "到期時股價",
   "kind": "money",
   "unit": "元"
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "option_type",
   "text": "此計算適用於買入（做多）賣權的損益。"
  },
  {
   "name": "transaction_fees",
   "text": "交易費用不包含在損益計算中。"
  }
 ],
 "invariants": [
  {
   "id": "pre_positive_financial_inputs",
   "kind": "pre",
   "text": "買入時股價、履約價、每股權利金必須為正數。",
   "check": "stock_price_at_purchase > 0 and strike_price > 0 and premium_paid > 0",
   "source": "dbc"
  },
  {
   "id": "pre_shares_per_option",
   "kind": "pre",
   "text": "每份合約股數必須為正整數。",
   "check": "shares_per_option == int(shares_per_option) and shares_per_option > 0",
   "source": "dbc"
  },
  {
   "id": "pre_final_stock_price_non_negative",
   "kind": "pre",
   "text": "到期時股價必須為非負數。",
   "check": "final_stock_price >= 0",
   "source": "dbc"
  },
  {
   "id": "post_otm_expiration",
   "kind": "post",
   "text": "若到期股價高於或等於履約價，選擇權無內在價值，損益為負權利金總額。",
   "check": "close(f(stock_price_at_purchase, strike_price, premium_paid, shares_per_option, strike_price + 10), -premium_paid * shares_per_option)",
   "source": "base_case"
  },
  {
   "id": "post_itm_max_profit_at_zero",
   "kind": "post",
   "text": "若到期股價為零，損益為 (履約價 - 權利金) × 每份合約股數。",
   "check": "close(f(stock_price_at_purchase, strike_price, premium_paid, shares_per_option, 0), (strike_price - premium_paid) * shares_per_option)",
   "source": "base_case"
  },
  {
   "id": "post_very_small_premium",
   "kind": "post",
   "text": "若權利金極小，損益趨近於總內在價值。",
   "check": "close(f(stock_price_at_purchase, strike_price, 0.000001, shares_per_option, final_stock_price), max(strike_price - final_stock_price, 0) * shares_per_option)",
   "source": "base_case"
  },
  {
   "id": "post_break_even_point",
   "kind": "post",
   "text": "若到期股價等於履約價減去每股權利金（且不為負），則損益為零。",
   "check": "close(f(stock_price_at_purchase, strike_price, premium_paid, shares_per_option, max(0, strike_price - premium_paid)), 0)",
   "source": "base_case"
  },
  {
   "id": "meta_shares_scaling",
   "kind": "meta",
   "text": "每份合約股數加倍，總損益也加倍。",
   "check": "close(f(stock_price_at_purchase, strike_price, premium_paid, 2 * shares_per_option, final_stock_price), 2 * result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_premium_shift",
   "kind": "meta",
   "text": "每股權利金增加一單位，總損益減少每份合約股數。",
   "check": "close(f(stock_price_at_purchase, strike_price, premium_paid + 1, shares_per_option, final_stock_price), result - shares_per_option)",
   "source": "metamorphic"
  },
  {
   "id": "meta_strike_shift_itm_max",
   "kind": "meta",
   "text": "若到期股價為零，履約價增加一單位，總損益增加每份合約股數。",
   "check": "close(f(stock_price_at_purchase, strike_price + 1, premium_paid, shares_per_option, 0), f(stock_price_at_purchase, strike_price, premium_paid, shares_per_option, 0) + shares_per_option)",
   "source": "metamorphic"
  },
  {
   "id": "meta_final_price_monotonicity",
   "kind": "meta",
   "text": "到期股價越高，總損益不會增加。",
   "check": "f(stock_price_at_purchase, strike_price, premium_paid, shares_per_option, final_stock_price + 1) <= result + 1e-9",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "參數 `stock_price_at_purchase` 雖然是輸入之一，但其值不影響此函數的損益計算結果。此卡片中的不變式已反映此行為。"
}

{
 "title": "遠期匯率計算",
 "topic": "外匯市場",
 "output": {
  "name": "forward_rate",
  "label": "遠期匯率",
  "unit": "數字"
 },
 "slots": [
  {
   "name": "spot_rate",
   "label": "即期匯率",
   "kind": "number",
   "unit": "數字"
  },
  {
   "name": "domestic_interest_rate",
   "label": "本國利率",
   "kind": "rate",
   "unit": "小數"
  },
  {
   "name": "foreign_interest_rate",
   "label": "外國利率",
   "kind": "rate",
   "unit": "小數"
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "period",
   "text": "計算基於單一期間（例如一年），無須輸入期間參數。"
  },
  {
   "name": "compounding",
   "text": "利率採單期複利計算，而非連續複利。"
  },
  {
   "name": "rates_format",
   "text": "利率以小數形式輸入（例如 3% 應輸入為 0.03）。"
  },
  {
   "name": "no_friction",
   "text": "不考慮交易成本、稅金或資本流動限制，假設資金可自由流動。"
  }
 ],
 "invariants": [
  {
   "id": "pre_spot_positive",
   "kind": "pre",
   "text": "即期匯率必須為正值。",
   "check": "spot_rate > 0",
   "source": "dbc"
  },
  {
   "id": "pre_domestic_rate_valid",
   "kind": "pre",
   "text": "本國利率加一必須為正值，以確保折現因子有效。",
   "check": "1 + domestic_interest_rate > 0",
   "source": "dbc"
  },
  {
   "id": "pre_foreign_rate_valid",
   "kind": "pre",
   "text": "外國利率加一必須為正值，以確保折現因子有效且避免除以零。",
   "check": "1 + foreign_interest_rate > 0",
   "source": "dbc"
  },
  {
   "id": "post_rates_equal",
   "kind": "post",
   "text": "若本國與外國利率相等，遠期匯率應等於即期匯率。",
   "check": "close(f(spot_rate, domestic_interest_rate, domestic_interest_rate), spot_rate)",
   "source": "base_case"
  },
  {
   "id": "post_zero_spot",
   "kind": "post",
   "text": "若即期匯率為零，則遠期匯率亦為零。",
   "check": "close(f(0, domestic_interest_rate, foreign_interest_rate), 0)",
   "source": "base_case"
  },
  {
   "id": "post_zero_rates",
   "kind": "post",
   "text": "若本國與外國利率皆為零，遠期匯率應等於即期匯率。",
   "check": "close(f(spot_rate, 0, 0), spot_rate)",
   "source": "base_case"
  },
  {
   "id": "meta_linear_spot",
   "kind": "meta",
   "text": "即期匯率加倍，遠期匯率也應加倍。",
   "check": "close(f(2 * spot_rate, domestic_interest_rate, foreign_interest_rate), 2 * result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_monotone_domestic_rate",
   "kind": "meta",
   "text": "在其他條件不變下，本國利率提高，遠期匯率應不減。",
   "check": "f(spot_rate, domestic_interest_rate + 0.01, foreign_interest_rate) >= result - 1e-9",
   "source": "monotonicity"
  },
  {
   "id": "meta_monotone_foreign_rate",
   "kind": "meta",
   "text": "在其他條件不變下，外國利率提高，遠期匯率應不增。",
   "check": "f(spot_rate, domestic_interest_rate, foreign_interest_rate + 0.01) <= result + 1e-9",
   "source": "monotonicity"
  },
  {
   "id": "meta_reciprocal_rates",
   "kind": "meta",
   "text": "若將本國與外國利率互換，則新的遠期匯率與原遠期匯率相乘應等於即期匯率的平方。",
   "check": "close(f(spot_rate, domestic_interest_rate, foreign_interest_rate) * f(spot_rate, foreign_interest_rate, domestic_interest_rate), spot_rate * spot_rate)",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此卡片涵蓋了基於利率平價理論計算遠期匯率的核心邏輯，假設為單一期間且無交易成本或稅金。它明確了輸入要求、固定假設及程式行為應滿足的關鍵不變量。"
}

{
 "title": "稅務負債計算",
 "topic": "稅務",
 "output": {
  "name": "tax_liability",
  "label": "總稅務負債",
  "unit": "元"
 },
 "slots": [
  {
   "name": "taxable_income",
   "label": "應稅所得",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "tax_brackets",
   "label": "稅級門檻",
   "kind": "list",
   "unit": "元"
  },
  {
   "name": "tax_rates",
   "label": "稅率",
   "kind": "list",
   "unit": "小數"
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "progressive_system",
   "text": "採用累進稅制，不同所得區間適用不同稅率。"
  },
  {
   "name": "rates_decimal",
   "text": "稅率以小數形式表示（例如，10% 寫為 0.10）。"
  },
  {
   "name": "highest_rate_applies",
   "text": "超過最高稅級門檻的所得，適用最高稅率。"
  }
 ],
 "invariants": [
  {
   "id": "pre_income_non_negative",
   "kind": "pre",
   "text": "應稅所得必須非負。",
   "check": "taxable_income >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_lengths_match",
   "kind": "pre",
   "text": "稅級門檻與稅率列表的長度必須一致。",
   "check": "len(tax_brackets) == len(tax_rates)",
   "source": "dbc"
  },
  {
   "id": "pre_brackets_non_empty",
   "kind": "pre",
   "text": "稅級門檻列表不能為空。",
   "check": "len(tax_brackets) > 0",
   "source": "dbc"
  },
  {
   "id": "pre_brackets_sorted",
   "kind": "pre",
   "text": "稅級門檻必須按嚴格遞增順序排列。",
