   "kind": "meta",
   "text": "若所有稅率同比例放大，則稅務負債也應同比例放大。",
   "check": "k = 0.5; close(f(taxable_income, tax_brackets, [r * k for r in tax_rates]), result * k)",
   "source": "metamorphic"
  },
