   "kind": "meta",
   "text": "應稅所得增加時，稅務負債不應減少。",
   "check": "f(taxable_income=taxable_income + 100, tax_brackets=tax_brackets, tax_rates=tax_rates) >= result - 1e-9",
   "source": "metamorphic"
  }
