  },
  {
   "id": "pre_period_type",
   "kind": "pre",
   "text": "期間必須是整數",
   "check": "isinstance(period, int)",
   "source": "dbc"
  },
  {
   "id": "pre_period_range",
   "kind": "pre",
   "text": "期間必須大於 0 且不大於價格列表的長度",
   "check": "0 < period <= len(prices)",
   "source": "dbc"
  },
  {
   "id": "post_output_length",
   "kind": "post",
   "text": "結果列表的長度應為 `len(prices) - period + 1`",
   "check": "len(result) == len(prices) - period + 1",
   "source": "dbc"
  },
  {
   "id": "post_period_one",
   "kind": "post",
   "text": "當期間為 1 時，移動平均值列表應與原始價格列表相同",
