   "source": "dbc"
  },
  {
   "id": "pre_num_years",
   "kind": "pre",
   "text": "年數必須大於零",
   "check": "num_years > 0",
   "source": "dbc"
  },
  {
   "id": "post_zero_growth",
   "kind": "post",
   "text": "若初始價值與最終價值相等，則成長率為零",
