  "label": "正量指標",
  "unit": "點"
 },
 "slots": [
  {
   "name": "pvi_previous",
   "label": "前一日正量指標",
   "kind": "number",
   "unit": "點"
  },
  {
   "name": "closing_price_today",
   "label": "今日收盤價",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "closing_price_yesterday",
   "label": "昨日收盤價",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "current_volume",
   "label": "今日成交量",
   "kind": "count",
   "unit": "股"
  },
  {
   "name": "previous_volume",
   "label": "前一日成交量",
   "kind": "count",
   "unit": "股"
  }
 ],
 "conventions": [],
 "fixed": [],
 "invariants": [
  {
   "id": "pre_pvi_previous_non_negative",
   "kind": "pre",
   "text": "前一日正量指標應為非負數。",
   "check": "pvi_previous >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_prices_positive",
   "kind": "pre",
   "text": "今日與昨日收盤價應為正數。",
   "check": "closing_price_today > 0 and closing_price_yesterday > 0",
   "source": "dbc"
  },
  {
   "id": "pre_volumes_non_negative",
   "kind": "pre",
   "text": "今日與前一日成交量應為非負數。",
   "check": "current_volume >= 0 and previous_volume >= 0",
   "source": "dbc"
  },
  {
   "id": "post_no_volume_increase_no_change",
   "kind": "post",
   "text": "若今日成交量不大於前一日成交量，則正量指標不變。",
   "check": "current_volume <= previous_volume and close(result, pvi_previous)",
   "source": "base_case"
  },
  {
   "id": "post_no_price_change_no_pvi_change",
   "kind": "post",
   "text": "若今日成交量大於前一日成交量，但收盤價無變化，則正量指標不變。",
   "check": "current_volume > previous_volume and close(f(pvi_previous, closing_price_yesterday, closing_price_yesterday, current_volume, previous_volume), pvi_previous)",
   "source": "base_case"
  },
  {
   "id": "post_zero_pvi_previous_stays_zero",
   "kind": "post",
   "text": "若前一日正量指標為零，且今日成交量大於前一日成交量，則正量指標仍為零。",
   "check": "current_volume > previous_volume and close(f(0, closing_price_today, closing_price_yesterday, current_volume, previous_volume), 0)",
   "source": "base_case"
  },
  {
   "id": "meta_pvi_previous_scaling",
   "kind": "meta",
   "text": "若今日成交量大於前一日成交量，前一日正量指標按比例縮放，結果也應按相同比例縮放。",
   "check": "current_volume > previous_volume and close(f(2 * pvi_previous, closing_price_today, closing_price_yesterday, current_volume, previous_volume), 2 * result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_monotonic_price_increase",
   "kind": "meta",
   "text": "若今日成交量大於前一日成交量且前一日PVI為正，當今日收盤價上升時，正量指標應增加或不變。",
   "check": "current_volume > previous_volume and pvi_previous > 0 and f(pvi_previous, closing_price_today + 1, closing_price_yesterday, current_volume, previous_volume) >= result - 1e-9",
   "source": "metamorphic"
  },
  {
   "id": "meta_monotonic_price_decrease",
   "kind": "meta",
   "text": "若今日成交量大於前一日成交量且前一日PVI為正，當今日收盤價下降時，正量指標應減少或不變。",
   "check": "current_volume > previous_volume and pvi_previous > 0 and f(pvi_previous, closing_price_today - 1, closing_price_yesterday, current_volume, previous_volume) <= result + 1e-9",
   "source": "metamorphic"
  },
  {
   "id": "meta_volume_threshold_effect",
   "kind": "meta",
   "text": "當今日成交量從不大於前一日變為大於前一日時，PVI應從不變轉為根據價格變化調整。",
   "check": "close(f(pvi_previous, closing_price_today, closing_price_yesterday, previous_volume, previous_volume), pvi_previous) and not close(f(pvi_previous, closing_price_today, closing_price_yesterday, previous_volume + 1, previous_volume), pvi_previous) if closing_price_today != closing_price_yesterday else True",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此卡片涵蓋了正量指標計算的核心邏輯，包括輸入約束、無成交量增加時的行為、無價格變化時的行為、以及PVI值和價格變化的單調性。由於此計算不涉及時間序列或複雜的金融慣例，因此沒有定義額外的慣例或固定假設。"
}

