   "kind": "pre",
   "text": "初始價值必須為正數，避免除以零或導致無意義的計算",
   "check": "start_value > 0",
   "source": "dbc"
  },
  {
   "id": "pre_end_value",
   "kind": "pre",
   "text": "最終價值必須為非負數",
   "check": "end_value >= 0",
