   "id": "pre_periods",
   "kind": "pre",
   "text": "期間數必須是正整數",
   "check": "periods == int(periods) and periods > 0",
   "source": "dbc"
  },
  {
   "id": "base_one_period",
   "kind": "post",
   "text": "期間為一年時，複合年均成長率等於簡單成長率",
   "check": "close(f(start_value, end_value, 1), end_value / start_value - 1)",
   "source": "induction"
  },
  {
   "id": "base_no_growth",
   "kind": "post",
   "text": "初始價值等於最終價值時，複合年均成長率為 0",
