  {
   "name": "prior_19_day_ema",
   "label": "前一日19天ANA指數移動平均",
   "kind": "number",
   "unit": "家"
  },
  {
   "name": "prior_39_day_ema",
   "label": "前一日39天ANA指數移動平均",
   "kind": "number",
   "unit": "家"
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "smoothing_factors",
   "text": "19天EMA的平滑因子固定為0.10，39天EMA的平滑因子固定為0.05。"
