{
 "title": "共變數",
 "topic": "財務分析",
 "output": {
  "name": "covariance",
  "label": "共變數",
  "unit": "無單位"
 },
 "slots": [
  {
   "name": "returns_x",
   "label": "資產 X 報酬率",
   "kind": "list",
   "unit": "小數"
  },
  {
   "name": "returns_y",
   "label": "資產 Y 報酬率",
   "kind": "list",
   "unit": "小數"
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "covariance_type",
   "text": "計算樣本共變數（分母為 n-1）"
  },
  {
   "name": "return_format",
   "text": "輸入的報酬率為小數形式（例如 5% 寫成 0.05）"
  }
 ],
 "invariants": [
  {
   "id": "pre_length_match",
   "kind": "pre",
   "text": "兩個報酬率列表的長度必須相同",
   "check": "len(returns_x) == len(returns_y)",
   "source": "dbc"
  },
  {
   "id": "pre_min_length",
   "kind": "pre",
   "text": "列表長度必須至少為 2（計算樣本共變數需要至少兩個數據點）",
   "check": "len(returns_x) >= 2",
   "source": "dbc"
  },
  {
   "id": "meta_symmetry",
   "kind": "meta",
   "text": "資產 X 和 Y 的共變數與資產 Y 和 X 的共變數相同",
   "check": "close(f(returns_x, returns_y), f(returns_y, returns_x))",
   "source": "metamorphic"
  },
  {
   "id": "meta_add_constant_x",
   "kind": "meta",
   "text": "若資產 X 的所有報酬率都加上一個常數，共變數不變",
   "check": "close(f([r + 10.0 for r in returns_x], returns_y), result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_add_constant_y",
   "kind": "meta",
   "text": "若資產 Y 的所有報酬率都加上一個常數，共變數不變",
   "check": "close(f(returns_x, [r + 10.0 for r in returns_y]), result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_scale_x",
   "kind": "meta",
   "text": "若資產 X 的所有報酬率都乘以一個常數 k，共變數也乘以 k",
   "check": "close(f([r * 2.0 for r in returns_x], returns_y), 2.0 * result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_scale_y",
   "kind": "meta",
   "text": "若資產 Y 的所有報酬率都乘以一個常數 k，共變數也乘以 k",
   "check": "close(f(returns_x, [r * 2.0 for r in returns_y]), 2.0 * result)",
   "source": "metamorphic"
  },
  {
   "id": "post_constant_list_x",
   "kind": "post",
   "text": "若其中一個資產的報酬率始終為常數，則共變數為 0",
   "check": "close(f([5.0] * len(returns_x), returns_y), 0.0)",
   "source": "base_case"
  },
  {
   "id": "post_constant_list_y",
   "kind": "post",
   "text": "若其中一個資產的報酬率始終為常數，則共變數為 0",
   "check": "close(f(returns_x, [5.0] * len(returns_y)), 0.0)",
   "source": "base_case"
  },
  {
   "id": "post_self_covariance_constant",
   "kind": "post",
   "text": "資產與自身的共變數，若報酬率為常數，則為 0",
   "check": "close(f([5.0, 5.0], [5.0, 5.0]), 0.0)",
   "source": "base_case"
  },
  {
   "id": "post_self_covariance_simple",
   "kind": "post",
   "text": "資產與自身的共變數等於其樣本變異數（例如 [1, 2, 3] 的樣本變異數為 1）",
   "check": "close(f([1.0, 2.0, 3.0], [1.0, 2.0, 3.0]), 1.0)",
   "source": "base_case"
  }
 ],
 "completeness_note": "此卡片假設計算的是樣本共變數（分母為 n-1）。"
}

{
 "title": "貸款攤銷時間表",
 "topic": "財務計算",
