  {
   "name": "principal",
   "label": "本金",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "annual_interest_rate",
   "label": "年利率",
   "kind": "rate",
   "unit": "小數"
  },
  {
   "name": "years",
   "label": "年數",
   "kind": "count",
   "unit": "年"
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "payment_frequency",
   "text": "每月支付一次款項"
  },
  {
   "name": "compounding_frequency",
   "text": "每月複利一次"
  },
  {
   "name": "payment_timing",
   "text": "期末支付款項"
  },
  {
   "name": "no_taxes_fees",
   "text": "不考慮稅金或費用"
  }
 ],
 "invariants": [
  {
   "id": "pre_principal",
   "kind": "pre",
   "text": "本金必須大於零",
   "check": "principal > 0",
   "source": "dbc"
  },
  {
   "id": "pre_rate",
   "kind": "pre",
   "text": "年利率必須大於零",
   "check": "annual_interest_rate > 0",
   "source": "dbc"
  },
  {
   "id": "pre_years",
   "kind": "pre",
   "text": "年數必須是正整數",
   "check": "years == int(years) and years > 0",
   "source": "dbc"
  },
  {
   "id": "post_total_principal",
   "kind": "post",
   "text": "所有期數支付的本金總和應等於初始本金",
   "check": "close(sum(item['principal_paid'] for item in result), principal)",
   "source": "conservation"
  },
  {
   "id": "post_final_balance",
   "kind": "post",
   "text": "最後一期的剩餘本金應為零",
   "check": "close(result[-1]['remaining_balance'], 0)",
   "source": "dbc"
  },
  {
   "id": "post_num_periods",
   "kind": "post",
   "text": "時間表中的期數應等於總年數乘以 12（每月一期）",
   "check": "len(result) == years * 12",
