  },
  {
   "id": "post_period_sequence",
   "kind": "post",
   "text": "期數應從 1 依序遞增",
   "check": "all(result[i]['period'] == i + 1 for i in range(len(result)))",
   "source": "dbc"
  },
  {
   "id": "post_interest_recurrence",
   "kind": "post",
   "text": "每期支付的利息應基於前一期的剩餘本金計算",
   "check": "all(close(result[i]['interest_paid'], (principal if i == 0 else result[i-1]['remaining_balance']) * (annual_interest_rate / 12)) for i in range(len(result)))",
   "source": "recurrence"
  },
  {
   "id": "post_balance_recurrence",
   "kind": "post",
   "text": "每期結束時的剩餘本金應等於前一期剩餘本金減去當期支付的本金",
   "check": "all(close(result[i]['remaining_balance'], (principal if i == 0 else result[i-1]['remaining_balance']) - result[i]['principal_paid']) for i in range(len(result)))",
   "source": "recurrence"
  },
  {
   "id": "post_small_rate_principal",
   "kind": "post",
   "text": "當利率極低時，每期支付的本金應約等於總本金除以總期數",
   "check": "all(close(item['principal_paid'], principal / (years * 12), rel=1e-3) for item in f(principal, 1e-9, years))",
   "source": "base_case"
  },
  {
   "id": "post_small_rate_interest",
   "kind": "post",
   "text": "當利率極低時，每期支付的利息應約等於零",
   "check": "all(close(item['interest_paid'], 0, rel=1e-3) for item in f(principal, 1e-9, years))",
   "source": "base_case"
  },
  {
   "id": "meta_scale_principal",
   "kind": "meta",
   "text": "如果本金加倍，則每期支付的本金、利息和剩餘本金也應加倍",
   "check": "all(close(f(2 * principal, annual_interest_rate, years)[i]['principal_paid'], 2 * result[i]['principal_paid']) and close(f(2 * principal, annual_interest_rate, years)[i]['interest_paid'], 2 * result[i]['interest_paid']) and close(f(2 * principal, annual_interest_rate, years)[i]['remaining_balance'], 2 * result[i]['remaining_balance']) for i in range(len(result)))",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此計算卡沒有列出任何「約定」，因為參考函數已明確固定了所有相關約定，例如每月付款頻率、每月複利頻率以及期末付款時點。因此，使用者無需選擇任何選項。輸出是一個包含多個字典的列表，每個字典代表一個付款期，其中包含本金、利息和剩餘餘額的詳細資訊。"
}

{
 "title": "貨幣套利交易利潤計算",
 "topic": "國際金融",
