  {
   "name": "unweighted_data",
   "text": "所有數據點權重相同"
  }
 ],
 "invariants": [
  {
   "id": "pre_length_match",
   "kind": "pre",
   "text": "X 值列表與 Y 值列表長度必須相同",
   "check": "len(x_values) == len(y_values)",
   "source": "dbc"
  },
  {
   "id": "pre_min_points",
   "kind": "pre",
   "text": "數據點數量必須至少為 2 個，才能定義一條直線",
   "check": "len(x_values) >= 2",
   "source": "dbc"
  },
  {
   "id": "pre_x_variance",
   "kind": "pre",
   "text": "X 值列表不能所有值都相同，否則斜率無法定義（會導致除以零）",
   "check": "len(set(x_values)) > 1",
   "source": "dbc"
  },
  {
   "id": "post_horizontal_line",
   "kind": "post",
   "text": "若所有 Y 值相同 (例如 [C, C, C])，則迴歸直線的斜率為 0，截距為該 Y 值",
   "check": "close(f(x_values, [y_values[0]] * len(y_values))[0], 0) and close(f(x_values, [y_values[0]] * len(y_values))[1], y_values[0])",
   "source": "metamorphic"
  },
  {
   "id": "post_perfect_fit_y_eq_x",
   "kind": "post",
   "text": "若數據點完美落在 y = x 直線上，則迴歸直線的斜率為 1，截距為 0",
