   "source": "metamorphic"
  },
  {
   "id": "post_passes_through_centroid",
   "kind": "post",
   "text": "迴歸直線必須通過數據點的重心 (X 平均值, Y 平均值)",
   "check": "close(result[1] + result[0] * (sum(x_values) / len(x_values)), sum(y_values) / len(y_values))",
