  },
  {
   "id": "post_output_structure",
   "kind": "post",
   "text": "輸出必須是包含三條通道線的字典，且每條線都是數字列表",
   "check": "isinstance(result, dict) and all(k in result for k in ['middle_line', 'upper_band', 'lower_band']) and all(isinstance(v, list) and all(isinstance(x, (int, float)) for x in v) for v in result.values())",
   "source": "dbc"
  },
  {
   "id": "post_output_lengths_match",
   "kind": "post",
   "text": "所有通道線的長度必須一致",
