   "source": "base_case"
  },
  {
   "id": "post_constant_prices",
   "kind": "post",
   "text": "當價格序列恆定時，所有通道線的數值也應恆定於該價格",
   "check": "test_prices = [100.0] * (max(period_ema, period_atr) + 10); test_result = f(test_prices, period_ema, period_atr, multiplier); all(close(x, 100.0) for x in test_result['middle_line']) and all(close(x, 100.0) for x in test_result['upper_band']) and all(close(x, 100.0) for x in test_result['lower_band'])",
   "source": "base_case"
  },
  {
   "id": "meta_scale_prices",
   "kind": "meta",
   "text": "當價格序列等比例縮放時，所有通道線的數值也應等比例縮放",
   "check": "scaled_prices = [p * 2 for p in prices]; res_scaled = f(scaled_prices, period_ema, period_atr, multiplier); all(close(m_s, m_o * 2) for m_s, m_o in zip(res_scaled['middle_line'], result['middle_line'])) and all(close(u_s, u_o * 2) for u_s, u_o in zip(res_scaled['upper_band'], result['upper_band'])) and all(close(l_s, l_o * 2) for l_s, l_o in zip(res_scaled['lower_band'], result['lower_band']))",
   "source": "metamorphic"
  },
  {
   "id": "meta_invert_prices",
   "kind": "meta",
   "text": "當價格序列以某個基準點反轉時，中線也應反轉，上下軌線也應反轉",
   "check": "base_price = max(prices) + 10; inverted_prices = [base_price - p for p in prices]; res_inverted = f(inverted_prices, period_ema, period_atr, multiplier); all(close(m_i, base_price - m_o) for m_i, m_o in zip(res_inverted['middle_line'], result['middle_line'])) and all(close(u_i, base_price - u_o) for u_i, u_o in zip(res_inverted['upper_band'], result['upper_band'])) and all(close(l_i, base_price - l_o) for l_i, l_o in zip(res_inverted['lower_band'], result['lower_band']))",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此卡片涵蓋了肯特納通道計算的關鍵輸入約束、輸出結構、基本行為和縮放特性。"
}

