   "label": "無風險利率",
   "kind": "rate",
   "unit": "小數"
  },
  {
   "name": "option_type",
   "label": "選擇權類型",
   "kind": "text",
   "unit": ""
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "option_model",
   "text": "僅適用於歐式選擇權，使用 Black-Scholes 模型"
  },
  {
   "name": "rate_format",
   "text": "無風險利率為小數形式（例如 5% 寫成 0.05）"
  },
  {
   "name": "time_unit",
   "text": "到期時間以年為單位"
  },
  {
   "name": "compounding",
   "text": "利率為連續複利"
  }
 ],
 "invariants": [
  {
   "id": "pre_option_price_positive",
   "kind": "pre",
   "text": "選擇權市價必須為正數",
   "check": "option_market_price > 0",
   "source": "dbc"
  },
  {
   "id": "pre_stock_price_positive",
   "kind": "pre",
   "text": "標的股價必須為正數",
   "check": "stock_price > 0",
   "source": "dbc"
  },
  {
   "id": "pre_strike_price_positive",
   "kind": "pre",
   "text": "履約價必須為正數",
   "check": "strike_price > 0",
   "source": "dbc"
  },
  {
   "id": "pre_time_positive",
   "kind": "pre",
   "text": "到期時間必須為正數",
   "check": "time_to_expiration > 0",
   "source": "dbc"
  },
  {
   "id": "pre_rate_non_negative",
   "kind": "pre",
   "text": "無風險利率必須為非負數",
   "check": "risk_free_rate >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_option_type_valid",
   "kind": "pre",
   "text": "選擇權類型必須是 'call' 或 'put'",
