   "source": "dbc"
  },
  {
   "id": "post_iv_range",
   "kind": "post",
   "text": "隱含波動率應為非負數且在合理範圍內（例如 0 到 500%）",
   "check": "0 <= result <= 5.0",
   "source": "dbc"
  },
  {
   "id": "post_zero_time_intrinsic_value_call",
   "kind": "post",
   "text": "當到期時間趨近於零時，若買權市價等於內含價值，則隱含波動率應趨近於零",
   "check": "close(f(max(0, stock_price - strike_price), stock_price, strike_price, 1e-9, risk_free_rate, 'call'), 0)",
   "source": "base_case"
  },
  {
   "id": "post_zero_time_intrinsic_value_put",
   "kind": "post",
   "text": "當到期時間趨近於零時，若賣權市價等於內含價值，則隱含波動率應趨近於零",
   "check": "close(f(max(0, strike_price - stock_price), stock_price, strike_price, 1e-9, risk_free_rate, 'put'), 0)",
