   "check": "(\n    (intrinsic_val := (max(0, stock_price - strike_price) if option_type == 'call' else max(0, strike_price - stock_price))) and\n    (new_price := option_market_price + 0.01) and\n    (new_price > intrinsic_val) and\n    (f(new_price, stock_price, strike_price, time_to_expiration, risk_free_rate, option_type) >= result - 1e-9)\n)",
   "source": "metamorphic"
  },
  {
   "id": "meta_put_call_parity",
   "kind": "meta",
   "text": "滿足買賣權平價關係的買權和賣權，其隱含波動率應相同",
   "check": "(\n    (option_type == 'call' and (\n        (synthetic_put_price := option_market_price - stock_price + strike_price * math.exp(-risk_free_rate * time_to_expiration)) > 0 and\n        close(f(synthetic_put_price, stock_price, strike_price, time_to_expiration, risk_free_rate, 'put'), result)\n    )) or\n    (option_type == 'put' and (\n        (synthetic_call_price := option_market_price + stock_price - strike_price * math.exp(-risk_free_rate * time_to_expiration)) > 0 and\n        close(f(synthetic_call_price, stock_price, strike_price, time_to_expiration, risk_free_rate, 'call'), result)\n    ))\n)",
   "source": "metamorphic"
  },
  {
   "id": "meta_scaling_prices",
   "kind": "meta",
   "text": "若股價、履約價和選擇權市價按相同比例縮放，隱含波動率應不變",
   "check": "close(f(option_market_price * 2.0, stock_price * 2.0, strike_price * 2.0, time_to_expiration, risk_free_rate, option_type), result)",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此卡片涵蓋了 Black-Scholes 模型下隱含波動率計算的主要輸入約束、結果範圍、基本情境和重要的模型特性（如單調性、買賣權平價關係和價格縮放不變性）。由於隱含波動率的計算涉及數值方法，可能存在收斂性問題或多重解的情況，但這些不變量旨在驗證其在理想情況下的行為。卡片不包含對數值方法具體實現的約束，例如迭代次數或初始猜測值。"
}

{
 "title": "線性迴歸分析",
 "topic": "統計分析",
 "output": {
  "name": "result",
  "label": "迴歸線斜率與截距",
  "unit": []
 },
 "slots": [
  {
   "name": "x_values",
   "label": "自變數資料點",
   "kind": "list",
   "unit": []
  },
  {
   "name": "y_values",
   "label": "應變數資料點",
   "kind": "list",
   "unit": []
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "method",
   "text": "使用最小平方法計算迴歸線"
  },
  {
   "name": "model",
   "text": "模型為 y = 斜率 × x + 截距"
  }
 ],
 "invariants": [
  {
   "id": "pre_length_equal",
   "kind": "pre",
   "text": "x_values 和 y_values 必須長度相等",
   "check": "len(x_values) == len(y_values)",
   "source": "dbc"
  },
  {
   "id": "pre_min_points",
   "kind": "pre",
   "text": "至少需要兩個資料點",
   "check": "len(x_values) >= 2",
   "source": "dbc"
  },
  {
   "id": "pre_variance_x",
   "kind": "pre",
   "text": "x_values 不能全部相同 (即 x_values 的變異數不能為零)",
   "check": "sum((x - sum(x_values)/len(x_values))**2 for x in x_values) > 1e-9",
   "source": "dbc"
  },
  {
   "id": "post_mean_point",
   "kind": "post",
   "text": "迴歸線必須通過資料點的平均值 (x_mean, y_mean)",
   "check": "mean_x = sum(x_values) / len(x_values); mean_y = sum(y_values) / len(y_values); close(mean_y, result[0] * mean_x + result[1])",
   "source": "property"
  },
  {
   "id": "post_perfect_horizontal",
   "kind": "post",
   "text": "如果所有 y_values 都相同，則斜率為 0，截距為該 y 值",
   "check": "y_const = y_values[0]; all(close(y, y_const) for y in y_values) and close(result[0], 0) and close(result[1], y_const)",
   "source": "base_case"
  },
  {
   "id": "post_sum_residuals_zero",
   "kind": "post",
   "text": "殘差之和必須為零",
   "check": "close(sum(y - (result[0] * x + result[1]) for x, y in zip(x_values, y_values)), 0)",
   "source": "property"
  },
  {
   "id": "meta_scaling_y",
   "kind": "meta",
   "text": "將 y_values 乘以常數 k，斜率和截距也會乘以 k",
   "check": "k = 2.0; scaled_y = [k * y for y in y_values]; scaled_slope, scaled_intercept = f(x_values, scaled_y); close(scaled_slope, k * result[0]) and close(scaled_intercept, k * result[1])",
   "source": "metamorphic"
  },
  {
   "id": "meta_offset_y",
   "kind": "meta",
   "text": "將 y_values 加上常數 c，斜率不變，截距增加 c",
   "check": "c = 10.0; offset_y = [y + c for y in y_values]; offset_slope, offset_intercept = f(x_values, offset_y); close(offset_slope, result[0]) and close(offset_intercept, result[1] + c)",
   "source": "metamorphic"
  },
  {
   "id": "meta_offset_x",
   "kind": "meta",
   "text": "將 x_values 加上常數 c，斜率不變，截距減少 c 乘以斜率",
   "check": "c = 5.0; offset_x = [x + c for x in x_values]; offset_slope, offset_intercept = f(offset_x, y_values); close(offset_slope, result[0]) and close(offset_intercept, result[1] - c * result[0])",
   "source": "metamorphic"
  },
  {
   "id": "meta_scaling_x",
   "kind": "meta",
   "text": "將 x_values 乘以常數 k，斜率會除以 k，截距不變",
   "check": "k = 3.0; scaled_x = [k * x for x in x_values]; scaled_slope, scaled_intercept = f(scaled_x, y_values); close(scaled_slope, result[0] / k) and close(scaled_intercept, result[1])",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此卡片涵蓋了線性迴歸的基本性質和常見的變換不變性，但未包含所有可能的統計性質，例如決定係數 (R-squared) 或標準誤差的相關性質。"
}

{
 "title": "加權平均資本成本",
 "topic": "企業財務",
 "output": {
  "name": "wacc",
  "label": "加權平均資本成本",
