  },
  {
   "name": "equity_value",
   "label": "權益市場價值",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "debt_value",
   "label": "債務市場價值",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "tax_rate",
   "label": "企業稅率",
   "kind": "rate",
   "unit": "小數"
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "debt_cost_interpretation",
   "text": "債務資金成本 (debt_cost) 被視為稅前成本，稅盾效果透過 (1 - tax_rate) 應用。"
  },
  {
   "name": "market_values",
   "text": "權益價值和債務價值均為市場價值。"
  },
  {
   "name": "constant_tax_rate",
   "text": "假設稅率在計算期間保持不變。"
  }
 ],
 "invariants": [
  {
   "id": "pre_equity_cost_non_negative",
   "kind": "pre",
   "text": "權益資金成本必須是非負數。",
   "check": "equity_cost >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_debt_cost_non_negative",
   "kind": "pre",
   "text": "債務資金成本必須是非負數。",
   "check": "debt_cost >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_equity_value_non_negative",
   "kind": "pre",
   "text": "權益市場價值必須是非負數。",
   "check": "equity_value >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_debt_value_non_negative",
   "kind": "pre",
   "text": "債務市場價值必須是非負數。",
   "check": "debt_value >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_tax_rate_range",
   "kind": "pre",
   "text": "企業稅率必須在 0 到 1 之間（含）。",
   "check": "0 <= tax_rate <= 1",
   "source": "dbc"
  },
  {
   "id": "pre_total_value_positive",
   "kind": "pre",
   "text": "總資本價值（權益加債務）必須為正數，以避免除以零。",
   "check": "equity_value + debt_value > 0",
   "source": "dbc"
  },
  {
   "id": "post_only_equity_financing",
   "kind": "post",
   "text": "若公司僅有權益融資（無債務），則 WACC 等於權益資金成本。",
   "check": "close(f(equity_cost, debt_cost, 100.0, 0.0, tax_rate), equity_cost)",
   "source": "base_case"
  },
  {
   "id": "post_only_debt_financing",
   "kind": "post",
   "text": "若公司僅有債務融資（無權益），則 WACC 等於債務資金成本乘以 (1 - 稅率)。",
   "check": "close(f(equity_cost, debt_cost, 0.0, 100.0, tax_rate), debt_cost * (1 - tax_rate))",
   "source": "base_case"
  },
  {
   "id": "post_zero_tax_equal_costs",
   "kind": "post",
   "text": "若稅率為零且權益與債務的稅前成本相等，則 WACC 等於該成本。",
   "check": "close(f(0.05, 0.05, 100.0, 200.0, 0.0), 0.05)",
   "source": "base_case"
  },
  {
   "id": "post_wacc_range",
   "kind": "post",
   "text": "WACC 必須介於權益資金成本與稅後債務資金成本之間。",
   "check": "min(equity_cost, debt_cost * (1 - tax_rate)) - 1e-9 <= result and result <= max(equity_cost, debt_cost * (1 - tax_rate)) + 1e-9",
   "source": "dbc"
  },
  {
   "id": "meta_scale_capital_structure",
   "kind": "meta",
   "text": "若權益價值和債務價值按相同比例縮放，WACC 應保持不變。",
   "check": "close(f(equity_cost, debt_cost, 2.0 * equity_value, 2.0 * debt_value, tax_rate), result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_scale_costs_zero_tax",
   "kind": "meta",
   "text": "若稅率為零，且權益與債務成本按相同比例縮放，則 WACC 也應按相同比例縮放。",
   "check": "close(f(2.0 * equity_cost, 2.0 * debt_cost, equity_value, debt_value, 0.0), 2.0 * f(equity_cost, debt_cost, equity_value, debt_value, 0.0))",
   "source": "metamorphic"
  },
  {
   "id": "meta_monotonic_tax_rate",
   "kind": "meta",
   "text": "提高稅率應導致 WACC 降低或保持不變（若無債務）。",
   "check": "f(equity_cost, debt_cost, equity_value, debt_value, min(1.0, tax_rate + 0.01)) <= result + 1e-9",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此卡片假設 debt_cost 為稅前成本，與原始函數說明中的『稅後成本』存在差異，但與函數的實際計算邏輯 (乘以 (1 - tax_rate)) 保持一致。"
}

{
 "title": "加權平均數",
 "topic": "統計計算",
 "output": {
