   "text": "對於兩個數值 [a, b] 的母體變異數為 (a-b)^2 / 4。",
   "check": "close(f(data_set=[1.0, 3.0], sample=False), 1.0)",
   "source": "base_case"
  },
  {
   "id": "meta_scaling_data",
