  {
   "id": "meta_monotone_initial_value",
   "kind": "meta",
   "text": "在分母為正的情況下，期初市值增加，報酬率應不增加。",
   "check": "denominator_val = initial_value + sum(cf * t for cf, t in zip(cash_flows, cash_flow_times)); denominator_val > 0 and f(initial_value + 10, final_value, cash_flows, cash_flow_times) <= result + 1e-9"
  }
