   "check": "all(r >= 0 for r in bid_rates + offer_rates)",
   "source": "dbc"
  },
  {
   "id": "pre_bid_le_offer",
   "kind": "pre",
   "text": "每個銀行的買入利率應小於或等於其賣出利率。",
   "check": "all(b <= o for b, o in zip(bid_rates, offer_rates))",
   "source": "dbc"
  },
  {
   "id": "post_uniform_rates",
   "kind": "post",
   "text": "若所有買入利率皆為 X 且所有賣出利率皆為 Y，則 JIBAR 利率為 (X+Y)/2。",
   "check": "close(f([0.05]*10, [0.06]*10), (0.05+0.06)/2)",
   "source": "metamorphic"
  },
  {
   "id": "post_result_in_trimmed_range",
   "kind": "post",
   "text": "計算出的 JIBAR 利率應介於修剪後的中間利率的最小值和最大值之間。",
   "check": "mid_rates_calc = [(b + o) / 2 for b, o in zip(bid_rates, offer_rates)]; trimmed_mid_rates_calc = sorted(mid_rates_calc)[2:-2]; min(trimmed_mid_rates_calc) <= result <= max(trimmed_mid_rates_calc)",
   "source": "dbc"
  },
  {
   "id": "meta_scaling",
   "kind": "meta",
   "text": "若所有買入和賣出利率都按比例 k 縮放，則 JIBAR 利率也應按比例 k 縮放。",
   "check": "close(f([2*b for b in bid_rates], [2*o for o in offer_rates]), 2 * result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_offset",
   "kind": "meta",
   "text": "若所有買入和賣出利率都增加一個常數 C，則 JIBAR 利率也應增加 C。",
   "check": "close(f([b+0.01 for b in bid_rates], [o+0.01 for o in offer_rates]), result + 0.01)",
   "source": "metamorphic"
  },
  {
   "id": "meta_symmetry_bid_offer",
   "kind": "meta",
   "text": "交換買入和賣出利率列表，結果應保持不變。",
   "check": "close(f(offer_rates, bid_rates), result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_order_independence",
   "kind": "meta",
   "text": "報價對的順序不應影響最終結果。",
   "check": "close(f(bid_rates[::-1], offer_rates[::-1]), result)",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此卡片涵蓋了 JIBAR 計算的主要輸入約束、基本行為和變換特性。由於 JIBAR 計算方法標準化，沒有額外的約定選項。"
}

