  },
  {
   "id": "pre_returns_elements_type",
   "kind": "pre",
   "text": "報酬率列表中的每個元素都必須是數字",
   "check": "all(isinstance(r, (int, float)) for r in returns)",
   "source": "dbc"
  },
  {
   "id": "pre_returns_greater_than_neg_1",
   "kind": "pre",
   "text": "所有報酬率必須大於 -1",
