   "source": "dbc"
  },
  {
   "id": "post_single_return",
   "kind": "post",
   "text": "單一報酬率的幾何平均數就是該報酬率本身",
   "check": "close(f([0.05]), 0.05)",
   "source": "base_case"
  },
  {
   "id": "post_zero_returns",
   "kind": "post",
   "text": "所有報酬率皆為 0 時，幾何平均數為 0",
   "check": "close(f([0.0] * 5), 0.0)",
   "source": "base_case"
  },
  {
   "id": "post_constant_returns",
   "kind": "post",
   "text": "所有報酬率皆為常數 k 時，幾何平均數為 k",
   "check": "close(f([0.03] * 4), 0.03)",
   "source": "base_case"
  },
  {
   "id": "post_recurrence_add_one",
   "kind": "post",
   "text": "增加一個報酬率時，新的幾何平均數與舊的關係",
