   "source": "dbc"
  },
  {
   "id": "pre_counts_within_total",
   "kind": "pre",
   "text": "新高股數與新低股數不能超過總股票數",
   "check": "new_highs <= total_stocks and new_lows <= total_stocks",
   "source": "dbc"
  },
  {
   "id": "pre_distinct_highs_lows",
   "kind": "pre",
   "text": "新高股數與新低股數之和不能超過總股票數（假設一檔股票不能同時是新高和新低）",
   "check": "new_highs + new_lows <= total_stocks",
