   "kind": "pre",
   "text": "未來價值必須大於零",
   "check": "future_value > 0",
   "source": "dbc"
  },
  {
   "id": "post_zero_rate",
   "kind": "post",
   "text": "當未來價值等於現在價值時，折現率為零",
