{
 "title": "資產年度折舊費用",
 "topic": "會計與財務",
 "output": {
  "name": "depreciation",
  "label": "年度折舊費用",
  "unit": "元"
 },
 "slots": [
  {
   "name": "cost",
   "label": "資產原始成本",
   "kind": "money",
   "unit": "元"
  },
  {
   "name": "useful_life",
   "label": "估計耐用年限",
   "kind": "count",
   "unit": "年"
  },
  {
   "name": "method",
   "label": "折舊方法",
   "kind": "text",
   "unit": ""
  }
 ],
 "conventions": [],
 "fixed": [
  {
   "name": "annual_basis",
   "text": "計算結果為年度折舊費用，不考慮部分年度折舊。"
  },
  {
   "name": "no_salvage_value",
   "text": "本計算模型假設資產無殘值，折舊計算不考慮殘值。特別是雙倍餘額遞減法，其計算結果可能超過資產成本，這與實際會計實務中會將折舊限制在 (成本 - 殘值) 範圍內有所不同。"
  }
 ],
 "invariants": [
  {
   "id": "pre_cost_non_negative",
   "kind": "pre",
   "text": "資產成本必須是非負數。",
   "check": "cost >= 0",
   "source": "dbc"
  },
  {
   "id": "pre_useful_life_positive_integer",
   "kind": "pre",
   "text": "耐用年限必須是正整數。",
   "check": "useful_life > 0 and useful_life == int(useful_life)",
   "source": "dbc"
  },
  {
   "id": "pre_method_valid",
   "kind": "pre",
   "text": "折舊方法必須是「straight_line」或「double_declining_balance」。",
   "check": "method in {\"straight_line\", \"double_declining_balance\"}",
   "source": "dbc"
  },
  {
   "id": "post_depreciation_non_negative",
   "kind": "post",
   "text": "年度折舊費用必須是非負數。",
   "check": "result >= 0",
   "source": "dbc"
  },
  {
   "id": "post_zero_cost",
   "kind": "post",
   "text": "當資產成本為零時，年度折舊費用為零。",
   "check": "close(f(cost=0, useful_life=useful_life, method=method), 0)",
   "source": "induction"
  },
  {
   "id": "post_straight_line_one_year",
   "kind": "post",
   "text": "若為直線法且耐用年限為一年，年度折舊費用等於資產成本。",
   "check": "close(f(cost=cost, useful_life=1, method=\"straight_line\"), cost)",
   "source": "induction"
  },
  {
   "id": "post_ddb_one_year",
   "kind": "post",
   "text": "若為雙倍餘額遞減法且耐用年限為一年，年度折舊費用為資產成本的兩倍。",
   "check": "close(f(cost=cost, useful_life=1, method=\"double_declining_balance\"), 2 * cost)",
   "source": "induction"
  },
  {
   "id": "meta_cost_scaling",
   "kind": "meta",
   "text": "資產成本加倍，年度折舊費用也加倍。",
   "check": "close(f(cost=2 * cost, useful_life=useful_life, method=method), 2 * result)",
   "source": "metamorphic"
  },
  {
   "id": "meta_useful_life_inverse_scaling",
   "kind": "meta",
   "text": "耐用年限加倍，年度折舊費用減半。",
   "check": "useful_life > 0 and close(f(cost=cost, useful_life=2 * useful_life, method=method), result / 2)",
   "source": "metamorphic"
  },
  {
   "id": "meta_useful_life_monotonicity",
   "kind": "meta",
   "text": "在成本為正的情況下，耐用年限增加，年度折舊費用不會增加。",
   "check": "cost > 0 and useful_life > 0 and f(cost=cost, useful_life=useful_life + 1, method=method) <= result + 1e-9",
   "source": "metamorphic"
  }
 ],
 "completeness_note": "此卡片基於提供的 `calculate_depreciation` 函數，該函數為簡化模型，未考慮殘值、部分年度折舊、折舊上限等實際會計情境。特別是雙倍餘額遞減法，其計算結果可能在某些情況下超過資產成本，這與實際會計準則有所不同。"
}

